function allocationBatchInputs(state,names,details={}){if(!Array.isArray(names)||!names.length)throw Error("请至少选择一位方案经理");if(!["normal","cross"].includes(state.mode))throw Error("此分配方式不支持批量选择");assertProjectAllocationActor(state);const selected=new Set,categories=new Set;return names.map(name=>{if(selected.has(name))throw Error("请勿重复选择同一位方案经理");selected.add(name);const manager=V68_SMS.find(sm=>sm.name===name);if(!manager)throw Error("请选择有效的方案经理");if(categories.has(manager.cat))throw Error(manager.cat+"品类只能选择一位方案经理");categories.add(manager.cat);const data={...details,...state,sm:name,cat:manager.cat};const error=v68ValidateAllocation(data)||v68AllocationConflict(data.project,data.cat,name);if(error)throw Error(manager.cat+"："+error);return data})}function allocationBatchCreate(state,names,details={},save=v3Save){const inputs=allocationBatchInputs(state,names,details);const before=TODOS.slice();const parent=TODOS.find(t=>t.id===state.sourceTodoId),beforeParent=parent?v3Copy(parent):null;try{const created=inputs.map(v68SubmitAllocationData);completeProjectAllocation(state.sourceTodoId,created);if(!save())throw Error("申请未保存，请检查浏览器存储空间后重试");return created}catch(error){TODOS.splice(0,TODOS.length,...before);if(parent&&beforeParent){Object.keys(parent).forEach(key=>delete parent[key]);Object.assign(parent,beforeParent)}throw error}}function allocationBatchRefresh(){const root=document.getElementById("allocationBatch");if(!root)return;const selected=[...root.querySelectorAll("input[data-sm]:checked")];const chosen=new Map(selected.map(input=>[input.dataset.cat,input.value]));const query=(root.querySelector("[data-sm-search]")?.value||"").trim().toLowerCase();for(const input of root.querySelectorAll("input[data-sm]")){const conflict=v68AllocationConflict(V68.allocation.project,input.dataset.cat,input.value);const occupied=chosen.has(input.dataset.cat)&&chosen.get(input.dataset.cat)!==input.value;input.disabled=!!conflict||occupied;const row=input.closest(".allocation-person");row.classList.toggle("selected",input.checked);row.classList.toggle("unavailable",input.disabled);row.querySelector("[data-sm-reason]").textContent=conflict||(occupied?"本品类已选择其他 SM":"");row.hidden=!!query&&!row.dataset.search.includes(query)}root.querySelector("[data-sm-count]").textContent="已选择 "+selected.length+" 位 SM · "+chosen.size+" 个品类";root.querySelector("[data-sm-tags]").innerHTML=selected.map(input=>`<span class="allocation-tag"><span>${esc(input.value)}<small>${esc(input.dataset.cat)}</small></span><button type="button" data-sm-remove="${esc(input.value)}" aria-label="移除${esc(input.value)}">×</button></span>`).join("");root.querySelector("[data-sm-placeholder]").hidden=selected.length>0;root.querySelector("[data-sm-empty]").hidden=[...root.querySelectorAll(".allocation-person")].some(row=>!row.hidden)}function allocationBatchToggle(open,returnFocus=false){const root=document.getElementById("allocationBatch");if(!root)return;const panel=root.querySelector("[data-sm-panel]"),trigger=root.querySelector("[data-sm-trigger]");root.classList.toggle("is-open",open);panel.hidden=!open;trigger.setAttribute("aria-expanded",String(open));if(open){allocationBatchRefresh();root.querySelector("[data-sm-search]").focus({preventScroll:true})}else{root.querySelector("[data-sm-search]").value="";allocationBatchRefresh();if(returnFocus)trigger.focus({preventScroll:true})}}window.addEventListener("keydown",event=>{if(event.key!=="Escape"||!document.querySelector("#mask.on #allocationBatch.is-open"))return;event.preventDefault();event.stopImmediatePropagation();allocationBatchToggle(false,true)},true);document.addEventListener("pointerdown",event=>{const root=document.querySelector("#mask.on #allocationBatch.is-open");if(root&&!root.contains(event.target))allocationBatchToggle(false)});const allocationBatchPreviousOpen=v68Allocation;v68Allocation=function(project,mode="normal"){const result=allocationBatchPreviousOpen(project,mode);if(!["normal","cross"].includes(mode)||!document.querySelector("#mask.on #v68SM")||V68.allocation?.project!==project||V68.allocation.mode!==mode)return result;const select=document.getElementById("v68SM"),field=select.closest(".v68-field");const picker=document.createElement("div");picker.id="allocationBatch";picker.className="v68-field full allocation-batch";const candidates=v68Candidates(project,"",mode);picker.innerHTML=`<div class="allocation-label"><strong id="allocationSMLabel">方案经理（SM） <span>可多选</span></strong><b data-sm-count aria-live="polite"></b></div><div class="allocation-select"><div class="allocation-control"><div class="allocation-tags" data-sm-tags></div><button type="button" class="allocation-trigger" data-sm-trigger aria-label="选择方案经理（可多选）" aria-expanded="false" aria-controls="allocationSMOptions"><span data-sm-placeholder>请选择方案经理，可多选</span><span class="allocation-chevron" aria-hidden="true">⌄</span></button></div><div class="allocation-menu" id="allocationSMOptions" data-sm-panel hidden><input type="search" data-sm-search aria-label="搜索方案经理、品类或区域" placeholder="搜索姓名、品类或区域"><div class="allocation-people" role="group" aria-labelledby="allocationSMLabel">${candidates.map(sm=>`<label class="allocation-person" data-search="${esc((sm.name+" "+sm.cat+" "+sm.regions.join(" ")).toLowerCase())}"><input type="checkbox" data-sm data-cat="${esc(sm.cat)}" value="${esc(sm.name)}" aria-label="${esc(sm.name+" · "+sm.cat)}"><span><span class="allocation-person-info"><strong>${esc(sm.name)}</strong><small>${esc(sm.cat)} · ${esc(sm.regions.join(" / "))}</small></span><small data-sm-reason></small></span></label>`).join("")}<p data-sm-empty hidden>没有匹配的方案经理</p></div><div class="allocation-menu-foot"><span>每个品类选择一位方案经理</span><button type="button" data-sm-done>完成选择</button></div></div></div><small>${mode==="normal"?"提交后，分别向所选 SM 发起确认商机待办。":"提交后，按所选 SM 分别生成跨区域审批待办，由总经办逐项审批。"}</small>`;field.replaceWith(picker);picker.addEventListener("change",allocationBatchRefresh);picker.querySelector("[data-sm-search]").addEventListener("input",allocationBatchRefresh);picker.addEventListener("click",event=>{const remove=event.target.closest("[data-sm-remove]");if(remove){const input=[...picker.querySelectorAll("input[data-sm]")].find(item=>item.value===remove.dataset.smRemove);if(input){input.checked=false;input.dispatchEvent(new Event("change",{bubbles:true}))}picker.querySelector("[data-sm-trigger]").focus({preventScroll:true});return}if(event.target.closest("[data-sm-done]"))return allocationBatchToggle(false,true);if(event.target.closest("[data-sm-trigger]")||event.target.classList.contains("allocation-control"))allocationBatchToggle(!picker.classList.contains("is-open"))});picker.querySelector("[data-sm-trigger]").addEventListener("keydown",event=>{if(event.key==="ArrowDown"||event.key==="ArrowUp"){event.preventDefault();allocationBatchToggle(true)}});allocationBatchRefresh();return result};const allocationBatchPreviousSubmit=v68SubmitAllocation;v68SubmitAllocation=async function(){const picker=document.querySelector("#mask.on #allocationBatch");if(!picker)return allocationBatchPreviousSubmit();if(V68.busy||!V68.allocation)return;if(v69UploadsBusy())return toast("附件正在上传，请稍候");const button=document.querySelector('[data-act="v68AllocationSubmit"]');V68.busy=true;if(button)button.disabled=true;try{const names=[...picker.querySelectorAll("input[data-sm]:checked")].map(input=>input.value);const state={...V68.allocation};const tasks=allocationBatchCreate(state,names,{reason:document.getElementById("v68Reason")?.value.trim()||"",attachments:v69UploadValues("allocationFiles"),evidence:{}});document.getElementById("mask").classList.remove("on");markPagesDirty();openPage("todos");toast(state.mode==="normal"?`已向 ${tasks.length} 位 SM 发起确认商机待办`:`已提交 ${tasks.length} 项跨区域商机审批`)}catch(error){toast(error.message);allocationBatchRefresh()}finally{V68.busy=false;if(button)button.disabled=false}};const allocationBatchPreviousFill=tdFillFields;tdFillFields=function(root,task){let count=allocationBatchPreviousFill(root,task);const picker=root.querySelector("#allocationBatch");if(picker&&!picker.querySelector("input[data-sm]:checked")){const candidate=picker.querySelector("input[data-sm]:not(:disabled)");if(candidate){candidate.checked=true;candidate.dispatchEvent(new Event("change",{bubbles:true}));count++}}return count};const allocationPreviousActions=todoActs;todoActs=function(task){const actions=allocationPreviousActions(task);return task?.type==="项目待办"?actions.filter(action=>action.act!=="todoEnd"):actions};const allocationPreviousHandle=handleAct;handleAct=function(button){const action=button?.dataset?.act;const id=button?.dataset?.id||(action==="todoConfirm"?todoPending?.id:"");if((action==="todoEnd"||action==="todoConfirm"&&todoPending?.action==="end")&&TODOS.find(task=>task.id===id)?.type==="项目待办"){return toast("完成商机分配后，项目待办自动标记为已处理")}return allocationPreviousHandle(button)};
